-4">@if(session('success'))<div class="alert alert-success">{{session('success')}}</div>@endif @isset($event) @if($event->budget?->total_budget !== null && $event->grand_total > $event->budget->total_budget)<div class="alert alert-warning"><strong>Budget cap exceeded.</strong> This event is ₹{{number_format($event->grand_total-$event->budget->total_budget,2)}} over the ₹{{number_format($event->budget->total_budget,2)}} cap.</div>@endif @endisset @yield('content')</main><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script><script>$('.select2').select2();const h=document.documentElement,b=document.getElementById('theme-toggle'),k='festiva-theme';function set(v){h.dataset.theme=v;b.textContent=v==='dark'?'☀':'◐'}set(localStorage.getItem(k)||'light');b.onclick=()=>{let v=h.dataset.theme==='dark'?'light':'dark';localStorage.setItem(k,v);set(v)}</script></body></html>
